import{j as e}from"./index-Q5tmBBoz.js";import{I as t}from"./InfoPage-CouG5ON_.js";import"./PageHeader-D19aNveu.js";function i(){return e.jsx(t,{title:"Data privacy (GDPR)",lead:"We respect your privacy and are open about how we use your personal data. This notice explains what we collect, why, and the rights you hold under data protection law.",crumbs:[{to:"/",label:"Home"},{to:"/about",label:"About"},{label:"Data privacy (GDPR)"}],sections:[{heading:"What we collect and why",intro:"Brightwell is the data controller in respect of most personal information we process about applicants, students, staff, alumni and visitors.",body:["We collect only what we need: contact details, academic records, fee and payment information, and — where required by law or funding — protected characteristics used for monitoring. For job applicants we also process application, reference and interview data.","We use your data to admit, enrol and educate you, to manage services such as accommodation and libraries, to keep people safe, and to meet our legal and regulatory obligations."],aside:{title:"Quick facts",rows:[["Controller","Brightwell University"],["Lawful bases","Contract, legal obligation, legitimate interest, consent"],["Data retention","Per the University archive schedule"],["International transfer","Minimised, with safeguards"]],links:[["/cookies","Cookie policy"],["/legal","Legal and regulatory"]]}},{heading:"Your rights",body:["Under data protection law you can ask to see the personal data we hold about you, have it corrected, erased or restricted, object to certain processing, and ask for a copy in a portable format.","Some rights are limited where processing is necessary for law, research or the functioning of the University. Where we rely on your consent, you may withdraw it at any time without affecting the lawfulness of processing before withdrawal."]},{heading:"How to contact us",body:["For any enquiry about how your personal data is handled, contact the Data Protection Officer, who aims to respond within one month."],aside:{title:"Contact the data protection team",rows:[["Data Protection Officer","dpo@brightwell.ng"],["Postal address","University Offices, Brightwell Campus"],["Response time","Within one month"]],links:[["/contact","Contact us"]]}}]})}export{i as default};
